def find_max(arr):
    max_val = arr[0]
    for x in arr:  # Loop through n elements
        if x > max_val:
            max_val = x
    return max_val

def binary_search(arr, target):
    left, right = 0, len(arr) - 1
    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return -1  # Halves search space each iteration
